CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,principal TEXT NOT NULL,workspace TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages(seq INTEGER PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_session ON messages(session_id,seq);
CREATE TABLE IF NOT EXISTS turns(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),state TEXT NOT NULL,config_revision TEXT NOT NULL,started_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS active_turn ON turns(session_id) WHERE state NOT IN ('completed','failed','interrupted');
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY,session_id TEXT NOT NULL,turn_id TEXT,at INTEGER NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_session ON events(session_id,seq);
CREATE TABLE IF NOT EXISTS tool_runs(turn_id TEXT NOT NULL,call_id TEXT NOT NULL,name TEXT NOT NULL,arguments TEXT NOT NULL,status TEXT NOT NULL,result TEXT,PRIMARY KEY(turn_id,call_id));
CREATE TABLE IF NOT EXISTS memories(id INTEGER PRIMARY KEY,principal TEXT NOT NULL,workspace TEXT NOT NULL,content TEXT NOT NULL,tags TEXT NOT NULL,created_at INTEGER NOT NULL,supersedes INTEGER REFERENCES memories(id));
CREATE INDEX IF NOT EXISTS memories_supersedes ON memories(supersedes);
CREATE INDEX IF NOT EXISTS memories_scope ON memories(principal,workspace,id);
CREATE TABLE IF NOT EXISTS memory_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT OR IGNORE INTO memory_revision VALUES(1,0);
CREATE TRIGGER IF NOT EXISTS memory_revision_insert AFTER INSERT ON memories BEGIN UPDATE memory_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS memory_revision_update AFTER UPDATE ON memories BEGIN UPDATE memory_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS memory_revision_delete AFTER DELETE ON memories BEGIN UPDATE memory_revision SET revision=revision+1 WHERE id=1; END;
CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(content,tags,content='memories',content_rowid='id',tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER IF NOT EXISTS memory_insert AFTER INSERT ON memories BEGIN INSERT INTO memories_fts(rowid,content,tags) VALUES(new.id,new.content,new.tags); END;
CREATE TRIGGER IF NOT EXISTS memory_delete AFTER DELETE ON memories BEGIN INSERT INTO memories_fts(memories_fts,rowid,content,tags) VALUES('delete',old.id,old.content,old.tags); END;
CREATE TRIGGER IF NOT EXISTS memory_update AFTER UPDATE ON memories BEGIN INSERT INTO memories_fts(memories_fts,rowid,content,tags) VALUES('delete',old.id,old.content,old.tags); INSERT INTO memories_fts(rowid,content,tags) VALUES(new.id,new.content,new.tags); END;
CREATE TABLE IF NOT EXISTS vectors(memory_id INTEGER NOT NULL REFERENCES memories(id),model TEXT NOT NULL,embedding TEXT NOT NULL,PRIMARY KEY(memory_id,model));
CREATE TABLE IF NOT EXISTS vector_models(model TEXT PRIMARY KEY,dimensions INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_access(hash TEXT NOT NULL,principal TEXT NOT NULL,PRIMARY KEY(hash,principal));
CREATE TABLE IF NOT EXISTS vector_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT OR IGNORE INTO vector_revision VALUES(1,0);
CREATE TRIGGER IF NOT EXISTS vector_insert AFTER INSERT ON vectors BEGIN UPDATE vector_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS vector_update AFTER UPDATE ON vectors BEGIN UPDATE vector_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS vector_delete AFTER DELETE ON vectors BEGIN UPDATE vector_revision SET revision=revision+1 WHERE id=1; END;
CREATE TABLE IF NOT EXISTS relations(id INTEGER PRIMARY KEY,principal TEXT NOT NULL,workspace TEXT NOT NULL,source INTEGER NOT NULL REFERENCES memories(id),relation TEXT NOT NULL,target INTEGER NOT NULL REFERENCES memories(id));
CREATE TABLE IF NOT EXISTS evidence(seq INTEGER PRIMARY KEY,hash TEXT NOT NULL UNIQUE,body TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS immutable_evidence_update BEFORE UPDATE ON evidence BEGIN SELECT RAISE(ABORT,'evidence is append-only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_evidence_delete BEFORE DELETE ON evidence BEGIN SELECT RAISE(ABORT,'evidence is append-only'); END;
CREATE TABLE IF NOT EXISTS inbound(platform TEXT NOT NULL,external_id TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(platform,external_id));
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,channel TEXT NOT NULL,destination TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inbox(seq INTEGER PRIMARY KEY,channel TEXT NOT NULL,external_id TEXT NOT NULL,principal TEXT NOT NULL,destination TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',error TEXT,UNIQUE(channel,external_id));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,principal TEXT NOT NULL,channel TEXT NOT NULL,destination TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS bindings(platform TEXT NOT NULL,channel TEXT NOT NULL,principal TEXT NOT NULL,session_id TEXT NOT NULL REFERENCES sessions(id),PRIMARY KEY(platform,channel,principal));
CREATE TABLE IF NOT EXISTS connector_cursors(name TEXT PRIMARY KEY,cursor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS learned_trajectories(signature TEXT PRIMARY KEY,status TEXT NOT NULL);
